def scenario(sid,mech,parent,incoming,question,field=None,tv=None,iv=None,source='SOURCE_DERIVED',extra=None):
 d=doc(incoming); decision=(syn.get(incoming) or truth.get(incoming,'REVIEW')) if incoming else 'CURATED_TRUSTED_SEED'; x={'scenario_id':sid,'mechanism':mech,'display_name':sid,'trusted_seed_document_ids':[parent],'incoming_document_id':incoming,'distractor_document_ids':[],'actual_decision':decision,'source_kind':source,'topic_display_name':question.split('的')[0],'queried_field':field,'trusted_value':tv,'incoming_value':iv,'primary_question':question,'demo_status':'GOOD_DEMO'}; x.update(extra or {}); return x
