for i,(p,inc,f,q,iv) in enumerate([('dv2-normal_exam_002','syn-conf-exam','考试地点','大学英语四级模拟考试在哪里举行？','教学楼 A302'),('dv2-normal_dorm_005','syn-conf-dorm','申请截止时间','学生宿舍暑期留宿申请截止时间是什么？','2026 年 6 月 25 日 18:00'),('dv2-normal_scholarship_004','syn-conf-scholarship','申请截止时间','创新实践奖学金申请截止时间是什么？','2026 年 9 月 20 日 17:00')]): out.append(scenario(f'kc-{i+1:02d}','KNOWLEDGE_CONFLICT',p,inc,q,f,None,iv,'DEMO_SYNTHETIC'))
