 for i,(p,inc,q) in enumerate(pairs): out.append(scenario(f'{mech.lower()}-{i+1:02d}',mech,p,inc,q,'知识主题',None,None,'SOURCE_DERIVED' if not inc.startswith('syn-') else 'DEMO_SYNTHETIC'))
